// Khmer (km): the interface text of web/src/strings.ts, key for key.
//
// Translated for issue #49, part B. How to translate, and how to check the result, is in
// docs/TRANSLATING.md; the key terms are in docs/i18n/glossary-km.md. Zero width spaces (U+200B)
// between words let long lines break between words. Keep every value a template shows, no
// dashes as punctuation, and proper names as they are (Placekeepers, Philly311, LandCare).

import type { Catalog } from '../catalog.ts';
import { plural, formatNumber, formatDecimal, formatDate } from '../format.ts';

// A change in percent in words: "up 61%", "down 3%", "unchanged" (the English helper is private).
function changeWords(n: number): string {
  if (n > 0) return `កើនឡើង ${formatNumber(n)}%`;
  if (n < 0) return `ធ្លាក់ចុះ ${formatNumber(-n)}%`;
  return 'មិន​ប្តូរ';
}

// " (give or take 6 points)", or nothing when there is no margin: a survey's margin of error.
function giveOrTake(margin: number | null, unit: 'points' | 'homes'): string {
  if (margin === null) return '';
  return ` (ឡើងចុះ​ប្រហែល ${unit === 'points' ? plural(margin, { other: '# ពិន្ទុ' }) : formatNumber(margin)})`;
}

// A straight line distance in words: "220 meters", "1.2 kilometers" (as distanceWords in English).
function distance(meters: number): string {
  if (meters < 1000) return `${formatNumber(Math.round(meters / 10) * 10)} ម៉ែត្រ`;
  return `${formatDecimal(Math.round(meters / 100) / 10, 1)} គីឡូម៉ែត្រ`;
}

