      mva: 'ការវិភាគ​តម្លៃ​ទីផ្សារ (Market Value Analysis) របស់​ទីក្រុង​រក​ឃើញថា​តម្លៃ​ផ្ទះ​កំពុង​ឡើង​ហួសពី​សមត្ថភាព​របស់​អ្នក​រស់នៅ​យូរអង្វែង',
