      assessments: 'តម្លៃ​ដែល​ទីក្រុង​វាយតម្លៃ',
      mva: 'ការវិភាគ​តម្លៃ​ទីផ្សារ​របស់​ទីក្រុង (Market Value Analysis)',
      companies: 'អ្នកទិញ​ដែល​ជា​ក្រុមហ៊ុន',
