      1: 'ទីក្រុង​ចុះបញ្ជី​ចង្កៀង LED នៅ​លើ​បង្គោល​នេះ។',
      2: 'ទីក្រុង​ចុះបញ្ជី​ចង្កៀង​សូដ្យូម​សម្ពាធ​ខ្ពស់​ចាស់​ជាង​នៅ​លើ​បង្គោល​នេះ។',
