    poleSource: 'មក​ពី​បញ្ជី​បង្គោល​ផ្លូវ​របស់ Streets Department ដែល​ធ្វើ​បច្ចុប្បន្នភាព​រាល់​សប្តាហ៍។',

    calmingLegend: 'ខ្នើយ ទួ ឬ​តុ​បន្ថយល្បឿន',
    calmingLegendNote: 'អ្នកជិតខាង​អាច​សុំ​ឱ្យ​ទីក្រុង​បន្ថយល្បឿន​ចរាចរណ៍​នៅ​លើ​ផ្លូវលំ​នៅ​ដ្ឋាន។',
    zoomStreets: 'សូម​ពង្រីក​ទៅ​សង្កាត់​ពីរបី ដើម្បី​មើល​វា។',
    calmingTitle: 'ការ​បន្ថយល្បឿន​ចរាចរណ៍',
