    window: (start, end) => `ពី ${start} ដល់ ${end}`,
    windowUnknown: 'ក្នុងរយៈពេល 12 ខែ',
    heatTitle: (window) => `ពេល​បង្រួម​ផែនទី៖ កន្លែង​ដែល​របាយការណ៍​ប្រមូល​ផ្តុំ។ ${window}។`,
    fewer: 'របាយការណ៍​តិច​ជាង',
    more: 'របាយការណ៍​ច្រើនជាង',
    binsTitle: 'ពេល​ពង្រីក​ជិត៖ របាយការណ៍​ក្នុង​តំបន់​នី​មួយៗ ទំហំ​ប្រហែល​មួយ​ប្លុក',
